//! MOV → MP4 on a clip generated by ffmpeg itself (no personal media).

#![allow(clippy::unwrap_used, clippy::expect_used)]

use std::process::Command;

use rollcopy_convert::{VideoMode, ffmpeg_available, probe, to_mp4, verify_mp4};

#[test]
fn remux_keeps_length_and_streams() {
    if !ffmpeg_available() {
        eprintln!("ffmpeg not installed; skipping");
        return;
    }
    let dir = tempfile::tempdir().unwrap();
    let src = dir.path().join("IMG_0001.MOV");
    let ok = Command::new("ffmpeg")
        .args(["-nostdin", "-v", "error", "-y"])
        .args([
            "-f",
            "lavfi",
            "-i",
            "testsrc=duration=2:size=320x240:rate=30",
        ])
        .args(["-f", "lavfi", "-i", "sine=duration=2"])
        .args([
            "-c:v",
            "libx264",
            "-pix_fmt",
            "yuv420p",
            "-c:a",
            "aac",
            "-shortest",
        ])
        .arg(&src)
        .status()
        .unwrap()
        .success();
    assert!(ok, "couldn't generate the test clip");

    // The queue writes to a `.part` name, so the container must not be
    // guessed from the extension.
    let dst = dir.path().join(".rollcopy-1-1-IMG_0001.MP4.part");
    to_mp4(&src, &dst, VideoMode::Remux).unwrap();
    let source = probe(&src).unwrap();
    let out = verify_mp4(&dst, source.duration_secs).unwrap();
    assert_eq!(out.codec, "h264");
    assert!(out.has_audio);
    assert_eq!((out.width, out.height), (320, 240));
}
